# Number Guessing Game Engine
def check_guess(guess: int, secret: int) -> str:
    if guess < secret:
        return "Too Low"
    elif guess > secret:
        return "Too High"
    else:
        return "Correct!"

def get_rating(attempts: int) -> str:
    if attempts <= 3:
        return "Amazing"
    elif attempts <= 6:
        return "Good"
    else:
        return "Keep practicing"

# Test simulation
secret = 42
print(check_guess(30, secret))  # Should print Too Low
print(check_guess(50, secret))  # Should print Too High
print(check_guess(42, secret))  # Should print Correct!

# CLI Contact Book Manager
def add_contact(book: dict, name: str, phone: str, email: str) -> dict:
    key = name.strip().lower()
    book[key] = {"name": name.strip(), "phone": phone.strip(), "email": email.strip()}
    return book

def find_contact(book: dict, name: str) -> dict | None:
    return book.get(name.strip().lower())

def delete_contact(book: dict, name: str) -> bool:
    key = name.strip().lower()
    if key in book:
        del book[key]
        return True
    return False

# Test operations
book = {}
add_contact(book, "Alice Smith", "555-0101", "alice@example.com")
print("Found:", find_contact(book, "alice smith"))

# File-based Quiz System & Validator
def parse_user_choice(raw_input: str, num_options: int) -> int | None:
    try:
        choice = int(raw_input.strip())
        if 1 <= choice <= num_options:
            return choice
        return None
    except (ValueError, TypeError):
        return None

def grade_quiz(answers: list[int], key: list[int]) -> dict:
    if not key:
        return {"score": 0, "pct": 0.0, "passed": False}
    correct = sum(1 for a, k in zip(answers, key) if a == k)
    pct = round((correct / len(key)) * 100, 1)
    return {"correct": correct, "total": len(key), "pct": pct, "passed": pct >= 70.0}

# Test simulation
print(parse_user_choice("3", 4))     # 3
print(parse_user_choice("invalid", 4)) # None
print(grade_quiz([1, 2, 3], [1, 2, 4])) # 66.7%, passed=False

import string
import random

def check_strength(password: str) -> int:
    if not password:
        return 0
    score = 0
    if len(password) >= 8:
        score += 1
    if any(c.isupper() for c in password):
        score += 1
    if any(c.islower() for c in password):
        score += 1
    if any(c.isdigit() for c in password):
        score += 1
    if any(c in string.punctuation for c in password):
        score += 1
    return score

def generate_password(length: int = 12) -> str:
    chars = string.ascii_letters + string.digits + "!@#$%^&*"
    return "".join(random.choice(chars) for _ in range(length))

# Test simulation
pwd = generate_password(14)
print("Generated:", pwd)
print("Strength (1-5):", check_strength(pwd))
